'use strict';
// Explicit city lookup only; never requests precise location or sends health records.
let careWeatherChoices=[],careWeatherRequest=0;
async function careWeatherFetch(url){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),12000);try{const r=await fetch(url,{signal:ctrl.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw Error('天气服务暂时不可用，请稍后重试。');return await r.json();}catch(e){throw Error(e.name==='AbortError'?'天气查询超时，请稍后重试。':e.message||'无法连接天气服务。');}finally{clearTimeout(timer);}}
function careWeatherModal(){showModal('天气与每日提醒',`<p>选择城市后查询天气，帮助你安排穿着和出行。只查询城市级天气，不获取精确定位，不发送孕期记录。</p><form data-form="care-weather"><label for="weather-city">城市名称</label><div class="care-question-row spaced"><input class="input" id="weather-city" name="city" required maxlength="80" placeholder="例如：北京 / Beijing"><button class="btn primary" type="submit">查询城市</button></div></form><div id="weather-result" class="spaced" role="status"></div><p class="small-copy spaced">天气数据来自 <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a>。提醒在打开页面时查看，不会后台推送。</p>`);careWeatherChoices=[];}
document.addEventListener('pet-weather',careWeatherModal);
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form="care-weather"]');if(!form)return;e.preventDefault();e.stopImmediatePropagation();const result=document.querySelector('#weather-result'),button=form.querySelector('button'),query=new FormData(form).get('city').trim();if(!query)return;const ticket=++careWeatherRequest;button.disabled=true;result.textContent='正在查找城市…';try{const response=await careWeatherFetch('https://geocoding-api.open-meteo.com/v1/search?'+new URLSearchParams({name:query,count:'5',language:'zh',format:'json'}));if(ticket!==careWeatherRequest||!result.isConnected)return;careWeatherChoices=(response.results||[]).filter(x=>Number.isFinite(x.latitude)&&Number.isFinite(x.longitude));result.innerHTML=careWeatherChoices.length?careWeatherChoices.map((c,i)=>`<button type="button" class="care-weather-choice btn" data-weather-city="${i}">${esc(c.name)} · ${esc(c.admin1||'')} ${esc(c.country||'')}</button>`).join(''):'没有找到城市，可以试试拼音或附近的城市。';}catch(err){if(result.isConnected)result.textContent=err.message;}finally{button.disabled=false;}},true);
document.addEventListener('click',async e=>{const button=e.target.closest('[data-weather-city]');if(!button)return;const city=careWeatherChoices[Number(button.dataset.weatherCity)];if(!city)return;const result=document.querySelector('#weather-result'),ticket=++careWeatherRequest;result.textContent='正在查询天气…';try{const data=await careWeatherFetch('https://api.open-meteo.com/v1/forecast?'+new URLSearchParams({latitude:String(city.latitude),longitude:String(city.longitude),current:'temperature_2m',daily:'temperature_2m_max,temperature_2m_min,precipitation_probability_max',past_days:'1',forecast_days:'1',timezone:'auto'}));if(ticket!==careWeatherRequest||!result.isConnected)return;const day=data.current?.time?.slice(0,10),i=data.daily?.time?.indexOf(day),current=data.current?.temperature_2m,hi=data.daily?.temperature_2m_max?.[i],lo=data.daily?.temperature_2m_min?.[i],previous=data.daily?.temperature_2m_max?.[i-1],rain=data.daily?.precipitation_probability_max?.[i];if(i<0||![current,hi,lo].every(Number.isFinite))throw Error('暂时没有完整天气数据，请稍后再试。');const drop=Number.isFinite(previous)?Math.round((previous-hi)*10)/10:0;const reminder=drop>=3?`今天预计最高温比昨天低 ${drop}°C，出门记得多带一件外套。`:lo<15?'今天早晚偏凉，可以带件外套，按体感增减衣物。':rain>=50?'今天有降水可能，出门记得带伞。':'出门前看看天气，也给自己留一点休息时间。';result.innerHTML=`<h3>${esc(city.name)} · ${esc(day)}</h3><p>当前 ${current}°C · 今日 ${lo}—${hi}°C${Number.isFinite(rain)?` · 降水概率 ${rain}%`:''}</p><div class="quote-box">${esc(reminder)}</div><p class="small-copy">查询时间：${esc(data.current.time.replace('T',' '))}（${esc(data.timezone||'当地时间')}）</p>`;const pet=document.querySelector('yunxin-pet');if(pet)pet.say(reminder);}catch(err){if(result.isConnected)result.textContent=err.message;}});
